let mutationWindowStart = 0;
mutationObserver = new MutationObserver(() => {
  const now = Date.now();
  if (!mutationTimer) mutationWindowStart = now; // open window on first event
  if (mutationTimer) clearTimeout(mutationTimer);
  const remaining = MAX_MUTATION_SCAN_DELAY_MS - (now - mutationWindowStart);
  const delay = Math.min(MUTATION_DEBOUNCE_MS, Math.max(0, remaining));
  mutationTimer = setTimeout(() => { mutationWindowStart = 0; /* re-scan */ }, delay);
}); // fires within 300ms if quiet, else forced at 1500ms cap

